import{z as i,x as P,o as l,c as p,q as s,j as n,D as E,d as r,s as o,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"VXLAN 与覆盖网","description":"","frontmatter":{"title":"VXLAN 与覆盖网","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vxlan-overlay.md","filePath":"cs/vxlan-overlay.md","lastUpdated":1791413859000}'),B={name:"cs/vxlan-overlay.md"};function d(V,a,N,D,C,T){const t=P("Mermaid");return l(),p("div",null,[a[2]||(a[2]=s('<h1 id="vxlan-与覆盖网" tabindex="-1">VXLAN 与覆盖网 <a class="header-anchor" href="#vxlan-与覆盖网" aria-label="Permalink to &quot;VXLAN 与覆盖网&quot;">​</a></h1><div class="epigraph"><p>租户以太网帧装进 UDP，外层 IP 在 Clos 上 ECMP；VNI 隔离广播域，底层不必再为每个租户拉 VLAN。</p><footer>—— 据 RFC 7348 VXLAN；数据中心网络实践整理</footer></div><p><a href="/cs/ecmp-hashing">上一课</a> 要熵。大二层 <a href="/cs/mac-learning">MAC 学习</a> 洪泛在数万口上爆炸。缺口是<strong>覆盖网</strong>：VXLAN 把 L2 帧 UDP 封装，VTEP 之间只跑 IP。本课不把 EVPN 控制面写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>VLAN 12 比特不够租户；STP 大域收敛差。VXLAN：24 比特 VNI，外层 UDP 目的 4789，源端口哈希内层流——把熵交给底层 ECMP。数据面仍可能未知单播洪泛（BUM），除非控制面（下一课 EVPN）分发 MAC。覆盖不提高 \\(C\\)，只改拓扑：物理是 L3 Clos，逻辑是 L2 段。</p><p>不要把 VXLAN 写成加密：那是 IPsec/MACSec 另加。</p><p><span class="marginnote">数字实例：VLAN 只有 12 比特，可用广播域约 4094 个；VXLAN 的 VNI 有 24 比特，可编 \\(2^{24} \\approx 1678\\) 万个租户段——云厂商一台物理机挂上千租户也不怕撞号。</span></p><p><span class="marginnote">RFC 7348 是信息性封装。实现差异在控制面。本课钉数据面。</span></p><h3 id="封装不提高" tabindex="-1">封装不提高 \\(C\\) <a class="header-anchor" href="#封装不提高" aria-label="Permalink to &quot;封装不提高 $C$&quot;">​</a></h3><p>VNI 隔离，UDP 源端口带熵。BUM 仍可能复制，除非 EVPN。底层 MTU 必须吃外层头。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：VM MAC → VTEP 封装 → 底层 IP/ECMP → 对端 VTEP 解封装。对照 VLAN tag：tag 在同一广播域里走；VXLAN 跨 IP 网。MTU：外层头约 50 字节，接住巨帧课，要底层更大或分片。</p>',12)),(l(),n(A,null,{default:E(()=>[o(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20L2%5B%22%E7%A7%9F%E6%88%B7%E4%BB%A5%E5%A4%AA%E7%BD%91%E5%B8%A7%22%5D%20--%3E%20ENC%5B%22VXLAN%2BUDP%2BIP%22%5D%0A%20%20ENC%20--%3E%20UND%5B%22%E5%BA%95%E5%B1%82%20ECMP%22%5D%0A%20%20UND%20--%3E%20DEC%5B%22VTEP%20%E8%A7%A3%E5%B0%81%E8%A3%85%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：覆盖网像快递——租户的以太网帧是包裹里的东西，VXLAN/UDP/IP 头是三层快递包装；中转站（底层 IP 路由）只看外层面单做 ECMP 分拣，从不拆开内层。UDP 源端口就是包装上那张哈希过流的面单号。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"与 MPLS VPN 对照：都是外层隧道 + 内层上下文（VNI vs 内层标签）。SR/GRE 可当另一种外层。PFC/RoCE 在覆盖下更难：外层丢包与内层无损语义冲突，后课 RoCE 会收回。",-1)),a[6]||(a[6]=e("p",null,"BUM：复制到所有 VTEP 或用底层组播；组播后课。无控制面时学习靠洪泛与源学习，像大号以太网。",-1)),(l(),n(A,null,{default:E(()=>[o(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22VM%20%E5%8F%91%E5%87%BA%E5%B9%BF%E6%92%AD%E6%88%96%E6%9C%AA%E7%9F%A5%E5%8D%95%E6%92%AD%22%5D%20--%3E%20IN%5B%22%E6%BA%90%20VTEP%20%E6%94%B6%E5%88%B0%22%5D%0A%20%20IN%20--%3E%20Q%7B%22%E6%9C%89%20EVPN%20%E6%8E%A7%E5%88%B6%E9%9D%A2%E5%90%97%3F%22%7D%0A%20%20Q%20--%20%E6%97%A0%20--%3E%20FLOOD%5B%22%E6%B4%AA%E6%B3%9B%E6%88%96%E5%BA%95%E5%B1%82%E7%BB%84%E6%92%AD%E5%A4%8D%E5%88%B6%E5%88%B0%E6%89%80%E6%9C%89%20VTEP%22%5D%0A%20%20Q%20--%20%E6%9C%89%20--%3E%20KNOWN%5B%22%E6%8C%89%E6%8E%A7%E5%88%B6%E9%9D%A2%E5%88%86%E5%8F%91%E7%9A%84%20MAC%20%E5%8D%95%E6%92%AD%E7%9B%B4%E8%BE%BE%22%5D%0A%20%20FLOOD%20--%3E%20OUT%5B%22%E5%AF%B9%E7%AB%AF%20VTEP%20%E8%A7%A3%E5%B0%81%E8%A3%85%E9%80%81%E8%BE%BE%22%5D%0A%20%20KNOWN%20--%3E%20OUT%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">常见误区：以为 VXLAN 自带加密或能无视 MTU。加密是 IPsec/MACSec 另加的事；外层头约 50 字节，1500 字节的内层帧到物理网上就是约 1550 字节——底层 MTU 不相应调大，就会静默分片或丢包。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Geneve 的 TLV 灵活性全文。EVPN 是下一课。后课默认：VXLAN 是 L2overL3 数据面；洪泛要靠控制面收敛。</p><p>硬件 VTEP 与软件 VTEP 性能差在 PPS，不在 RFC 格式。</p><p>下一课<a href="/cs/evpn">EVPN</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VNI 隔离；UDP 源端口带熵。</li><li>底层 L3 ECMP，逻辑 L2。</li><li>封装吃 MTU；BUM 是覆盖的痛。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 7348。</li></ul>',7))])}const L=i(B,[["render",d]]);export{h as __pageData,L as default};
